# Dataset storico: unisce game log, box score avanzati e difesa avversaria.
# Le medie rolling usano esclusivamente osservazioni precedenti alla riga.
richiedi_prepara <- function(x, n, nome) { m <- setdiff(n,names(x)); if(length(m)) stop(sprintf("%s privo di: %s",nome,paste(m,collapse=", ")),call.=FALSE) }
box_giocatori <- function(x) { if(!is.data.frame(x)||!"dataBoxScore"%in%names(x)||!length(x$dataBoxScore)) stop("box_data$dataBoxScore[[1]] assente.",call.=FALSE); b<-x$dataBoxScore[[1]]; richiedi_prepara(b,c("idGame","idPlayer"),"Box"); if(anyDuplicated(b[c("idGame","idPlayer")])) stop("Box duplicato.",call.=FALSE); b }
rolling_pre <- function(x, gruppi, metriche) {
  if(!requireNamespace("dplyr",quietly=TRUE)||!requireNamespace("slider",quietly=TRUE)) stop("Servono dplyr e slider.",call.=FALSE)
  x <- dplyr::arrange(x,dplyr::across(dplyr::all_of(c(gruppi,"dateGame","idGame")))) |> dplyr::group_by(dplyr::across(dplyr::all_of(gruppi)))
  dplyr::ungroup(dplyr::mutate(x,dplyr::across(dplyr::all_of(metriche),list(L1=~dplyr::coalesce(dplyr::lag(.x),0),L3=~dplyr::coalesce(slider::slide_dbl(.x,mean,.before=3,.after=-1),0),L5=~dplyr::coalesce(slider::slide_dbl(.x,mean,.before=5,.after=-1),0),L10=~dplyr::coalesce(slider::slide_dbl(.x,mean,.before=10,.after=-1),0),season_avg=~dplyr::coalesce(slider::slide_dbl(.x,mean,.before=Inf,.after=-1),0)),.names="{.col}_{.fn}")))
}
prepara_dataset_storico_modelli <- function(dati,box_data,dati_nba_t) {
  richiedi_prepara(dati,c("yearSeason","dateGame","idGame","idPlayer","slugOpponent","numberGamePlayerSeason","minutes","pts","ast","treb","fga","fta","tov","fgm","fg3m"),"Dati giocatori")
  b<-box_giocatori(box_data); dati$dateGame<-as.Date(dati$dateGame); extra<-setdiff(names(b),names(dati)); p<-dplyr::left_join(dati,b[,c("idGame","idPlayer",extra),drop=FALSE],by=c("idGame","idPlayer"))
  met<-intersect(c("minutes","pts","ast","treb","fga","fta","tov","fgm","fg3m","fg3a","fg2m","fg2a","ftm","oreb","dreb","stl","blk","pf","plusminus","fgContested","fg2Contested","screenAssist","ptsScreenAssist","deflections","boxOuts","boxOutsPlayerTREB","boxOutsPlayerTeamRebound","boxOutsOffense"),names(p)); p<-dplyr::mutate(p,dplyr::across(dplyr::all_of(met),~dplyr::coalesce(suppressWarnings(as.numeric(.x)),0)),TS_PCT=dplyr::if_else(fga+.44*fta==0,0,pts/(2*(fga+.44*fta))),EFG_PCT=dplyr::if_else(fga==0,0,(fgm+.5*fg3m)/fga),AST_TOV_RATIO=ast/(tov+1),EST_USG_PCT=dplyr::if_else(minutes==0,0,(fga+.44*fta+tov)/minutes),pts_ast=pts+ast,pts_treb=pts+treb,treb_ast=treb+ast,pts_reb_ast=pts+treb+ast); met<-c(met,"TS_PCT","EFG_PCT","AST_TOV_RATIO","EST_USG_PCT","pts_ast","pts_treb","treb_ast","pts_reb_ast"); p<-rolling_pre(p,c("idPlayer","yearSeason"),met); p$minutes_sum_L3<-p$minutes_L1+2*p$minutes_L3; p$pts_per_min_L5<-p$pts_L5/pmax(p$minutes_L5,1); p$fga_per_min_L5<-p$fga_L5/pmax(p$minutes_L5,1); hmet<-intersect(c("ast","treb","pts_ast","treb_ast"),met); h<-rolling_pre(p[,c("idGame","idPlayer","slugOpponent","dateGame",hmet),drop=FALSE],c("idPlayer","slugOpponent"),hmet); h<-h[,c("idGame","idPlayer",paste0(hmet,"_L3")),drop=FALSE]; names(h)[-(1:2)]<-paste0(hmet,"_H2H_L3"); p<-dplyr::left_join(p,h,by=c("idGame","idPlayer"))
  richiedi_prepara(dati_nba_t,c("yearSeason","dateGame","idGame","slugTeam","slugOpponent","ptsTeam","fgaTeam","ftaTeam","tovTeam","orebTeam"),"Dati squadre"); dati_nba_t$dateGame<-as.Date(dati_nba_t$dateGame); team<-grep("Team$",names(dati_nba_t),value=TRUE); team<-setdiff(team,"slugTeam"); o<-dati_nba_t[,c("idGame","slugTeam",team),drop=FALSE]; names(o)[-(1:2)]<-sub("Team$","Opp",team); d<-dplyr::left_join(dati_nba_t,o,by=c("idGame","slugOpponent"="slugTeam")); d<-dplyr::mutate(d,possessionsOpp=fgaOpp+.44*ftaOpp+tovOpp-orebOpp,defRatingOpp=dplyr::if_else(possessionsOpp>0,100*ptsOpp/possessionsOpp,0)); dm<-c(grep("Opp$",names(d),value=TRUE),"possessionsOpp","defRatingOpp"); d<-dplyr::mutate(d,dplyr::across(dplyr::all_of(dm),~dplyr::coalesce(as.numeric(.x),0))); d<-rolling_pre(d,c("slugTeam","yearSeason"),dm); cols<-c("idGame","slugTeam",grep("_(L1|L3|L5|L10|season_avg)$",names(d),value=TRUE)); out<-dplyr::left_join(p,d[,unique(cols),drop=FALSE],by=c("idGame","slugOpponent"="slugTeam")); out<-dplyr::arrange(out,dateGame,idGame,idPlayer); dplyr::mutate(out,eligible_modello_storico=numberGamePlayerSeason>5&minutes_season_avg>=15,row_id_master=dplyr::row_number())
}
